#!/usr/bin/env node
// Phase R4 — brand-registry coverage lint.
//
// Asserts the 1:1 invariant between the merchant pools and the
// generated brand registry:
//   - every merchant in any pool under synthetic-identity-pool/
//     merchants/ has a registry entry (logoUrl + colour + …)
//   - every registry entry resolves back to a pool merchant
//
// Runs against the committed registry at packages/sandbox-fixtures/
// brand-registry.json, which is regenerated by
// tools/build-brand-registry.mjs. If the registry file is missing
// (typical in a freshly-cloned repo before `npm run build:fixtures`),
// the lint short-circuits with a soft message — same posture as the
// fixture-package-dependent test suites.

import fs from 'node:fs';
import path from 'node:path';
import { loadAllPools, repoRoot } from './load-fixtures.mjs';
import { LintReporter } from './lint-shared.mjs';

const REGISTRY_PATH = path.join(repoRoot, 'packages/sandbox-fixtures/brand-registry.json');
const reporter = new LintReporter('lint-brand-registry-coverage');

if (!fs.existsSync(REGISTRY_PATH)) {
  console.log(
    'lint-brand-registry-coverage SKIPPED — brand-registry.json not built.\n' +
    '  Run `npm run build:brand-registry` (or `npm run build:fixtures`) to regenerate.'
  );
  process.exit(0);
}

const registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8'));
const records = registry?.records ?? {};
const registrySlugs = new Set(Object.keys(records));

const pools = loadAllPools();
const poolSlugs = new Set();
for (const pool of Object.values(pools.merchantsByCategory)) {
  for (const m of pool.merchants ?? []) {
    if (!m?.name) continue;
    const slug = slugify(m.name);
    if (!slug) continue;
    poolSlugs.add(slug);
    // Every pool merchant must have a registry entry.
    if (!registrySlugs.has(slug)) {
      reporter.add(
        `pool merchant "${m.name}" (slug "${slug}") has no brand-registry entry — ` +
        'run `npm run build:brand-registry` to regenerate.'
      );
    }
  }
}

// Every registry entry must trace back to a pool merchant.
for (const slug of registrySlugs) {
  if (!poolSlugs.has(slug)) {
    reporter.add(
      `brand-registry entry "${slug}" has no pool merchant — ` +
      'the merchant was removed from a pool but the registry wasn\'t rebuilt. ' +
      'Run `npm run build:brand-registry`.'
    );
  }
}

reporter.finish();

function slugify(name) {
  return String(name)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');
}
